import {useState} from 'react';
import {api} from './api';
import {Form,Field} from './ui';
const roles=[['manager','Business manager','Manage your organization, products and orders.'],['rider','Delivery rider','Apply for delivery work and manage assigned jobs.'],['dispatch','Dispatch','Coordinate authorized order preparation and handoffs.'],['transport','Transport','Prepare passenger journeys and a driver application.'],['shipment','Shipment','Prepare parcel quotation requests.'],['warehouse','Warehouse','Manage facilities, staff and warehouse operations.']];
export default function WorkspaceChoice(){const [open,setOpen]=useState(false);return <section className="role-choice"><div><h2>Make DEN work for you.</h2><p>Consumer is always available. You can also choose one role for your account.</p></div>{open?<Form submit="Confirm my role" onSubmit={async d=>{await api('/workspace','POST',d);location.assign('/consumer/');}}><Field label="Your additional role"><select name="role" required><option value="">Choose a role</option>{roles.map(([value,title])=><option value={value} key={value}>{title}</option>)}</select></Field><p className="small muted">Choose carefully: this selection is permanent. Other roles will not be available. Business, rider and operational approvals are still required before protected work.</p></Form>:<button className="secondary" onClick={()=>setOpen(true)}>Choose my role</button>}</section>;}
